"""Summarize workflow tables without modifying the node."""
import argparse
from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import re


REQUIRED = {
    'routines': ('name', 'every', 'last_time', 'last_code'),
    'schedule': ('name', 'at', 'claimed'),
}
UNITS = {'s': 1, 'm': 60, 'h': 3600, 'd': 86400}


def reject_constant(value):
    raise ValueError('non-finite JSON constant: ' + value)


def read_table(node, name, bad):
    try:
        with (node / 'wf' / (name + '.json')).open(encoding='utf-8') as stream:
            table = json.load(stream, parse_constant=reject_constant)
        if (not isinstance(table, dict) or table.get('contract') != 'wf-table/1'
                or not isinstance(table.get('columns'), list)
                or not all(isinstance(x, str) for x in table['columns'])
                or not isinstance(table.get('rows'), list)):
            raise ValueError('invalid table')
        return table['rows']
    except FileNotFoundError:
        return []
    except (OSError, UnicodeError, ValueError, TypeError, RecursionError):
        bad.append({'table': name, 'row': None, 'why': 'bad_table'})
        return []


def timestamp(text, tz):
    value = datetime.fromisoformat(text)
    return value.replace(tzinfo=tz) if value.tzinfo is None else value


def routine(row, now):
    every = row['every']
    if re.fullmatch(r'[1-9][0-9]*[rsmhd]', every) is None:
        raise ValueError('invalid interval')
    last = timestamp(row['last_time'], now.tzinfo) if row['last_time'] else None
    raw = row['last_code']
    if raw == '':
        code = None
    elif raw == 'running':
        code = raw
    elif re.fullmatch(r'[+-]?[0-9]+', raw):
        code = int(raw)
    else:
        raise ValueError('invalid code')
    due = None
    next_time = None
    if last is not None and every[-1] != 'r':
        due = last + timedelta(seconds=int(every[:-1]) * UNITS[every[-1]])
        next_time = due.astimezone(timezone.utc).replace(microsecond=0).isoformat().replace('+00:00', 'Z')
    if code == 'running':
        state = 'running'
    elif last is None:
        state = 'never'
    elif isinstance(code, int) and code != 0:
        state = 'failed'
    elif due is not None and now >= due:
        state = 'overdue'
    else:
        state = 'ok'
    return {'name': row['name'], 'every': every, 'last_time': row['last_time'] if last else None,
            'last_code': code, 'state': state, 'next': next_time}


def scheduled(row, now):
    at = timestamp(row['at'], now.tzinfo)
    state = 'interrupted' if row['claimed'] else ('due' if at <= now else 'pending')
    return {'name': row['name'], 'at': row['at'], 'state': state}


def collect(name, rows, now, bad):
    seen = set()
    result = []
    for index, row in enumerate(rows):
        item_name = row.get('name') if isinstance(row, dict) else None
        if isinstance(item_name, str) and item_name:
            if item_name in seen:
                bad.append({'table': name, 'row': index, 'why': 'dup_name'})
                continue
            seen.add(item_name)
        if (not isinstance(row, dict) or not isinstance(item_name, str) or not item_name
                or not all(isinstance(value, str) for value in row.values())
                or not all(key in row for key in REQUIRED[name])):
            bad.append({'table': name, 'row': index, 'why': 'bad_row'})
            continue
        try:
            result.append(routine(row, now) if name == 'routines' else scheduled(row, now))
        except (ValueError, OverflowError):
            bad.append({'table': name, 'row': index, 'why': 'bad_row'})
    return sorted(result, key=lambda item: item['name'])


def summarize(node, now):
    bad = []
    routines = collect('routines', read_table(node, 'routines', bad), now, bad)
    schedule = collect('schedule', read_table(node, 'schedule', bad), now, bad)
    counts = {
        'routines': {key: 0 for key in ('running', 'never', 'failed', 'overdue', 'ok')},
        'schedule': {key: 0 for key in ('interrupted', 'due', 'pending')},
    }
    for table, items in (('routines', routines), ('schedule', schedule)):
        for item in items:
            counts[table][item['state']] += 1
    bad.sort(key=lambda item: (item['table'], -1 if item['row'] is None else item['row'], item['why']))
    return {'v': 1, 'routines': routines, 'schedule': schedule, 'counts': counts, 'bad': bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description='Read-only workflow summary')
    parser.add_argument('folder', type=Path)
    parser.add_argument('--now', required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
        if now.tzinfo is None:
            raise ValueError('timezone required')
    except ValueError:
        parser.error('--now must be an ISO datetime with a timezone')
    if not args.folder.is_dir():
        parser.error('folder is not a directory')
    print(json.dumps(summarize(args.folder, now), separators=(',', ':')))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
